import math
from itertools import product

def solve():
    found_p = set()
    for a in range(1, 5):
        for b in range(1, 5):
            if math.gcd(a, b) != 1:
                continue
            p = a / b
            for N in range(1, 7):
                for c in product([0, 1, -1, 2, -2], repeat=N):
                    if all(val == 0 for val in c):
                        continue
                    s = 0
                    for i in range(N):
                        s += c[i] * (p**i)
                    if abs(s) < 1e-9:
                        found_p.add(p)
    return sorted(list(found_p))

print(solve())
